/**
 * 给按钮加上底部开关的图标（加在按钮原有内容之后，播放条上不显示，见 app.css）：图形（viewBox 内的 paths）放在 64×64 的方块里，
 * 四周留 inset；关闭时只显示图形，开启时为实心圆角方块、图形镂空（用遮罩实现）。返回 setOn(bool)。
 */
function toggleIcon(button, { viewBox = '0 0 64 64', paths, transform, inset = 0 }) {
  const id = `amll-toggle-${Math.random().toString(36).slice(2)}`;
  const svg = svgNode('svg', { class: 'amll-toggle-icon', viewBox: '0 0 64 64', 'aria-hidden': 'true' });
  const mask = svgNode('mask', { id, maskUnits: 'userSpaceOnUse', x: '0', y: '0', width: '64', height: '64' });
  const base = svgNode('path', { d: SQUIRCLE_64 });
  const glyph = svgNode('svg', { x: String(inset), y: String(inset), width: String(64 - inset * 2), height: String(64 - inset * 2), viewBox });
  glyph.append(...paths.map((d) => svgNode('path', transform ? { d, transform } : { d })));
  mask.append(base, glyph);
  svg.append(mask, svgNode('path', { d: SQUIRCLE_64, fill: 'currentColor', mask: `url(#${id})` }));
  button.append(svg);
  return (on) => {
    base.setAttribute('fill', on ? 'white' : 'black');
    glyph.setAttribute('fill', on ? 'black' : 'white');
    svg.classList.toggle('amll-toggle-icon--on', on);
  };
}

/**
 * 质量为 1 的弹簧从 0 到 1 的位移曲线，采样成 CSS 的 linear() 缓动，用来近似 react-full 里 framer-motion 的 spring 过渡；
 * duration 为位移稳定在终点 ±0.2% 以内所需的秒数
 */
function spring(stiffness, damping) {
  const w0 = Math.sqrt(stiffness);
  const zeta = damping / (2 * w0);
  let x;
  if (zeta < 1) {
    const wd = w0 * Math.sqrt(1 - zeta * zeta);
    x = (t) => 1 - Math.exp(-zeta * w0 * t) * (Math.cos(wd * t) + (zeta * w0 / wd) * Math.sin(wd * t));
  } else if (zeta > 1) {
    const wd = w0 * Math.sqrt(zeta * zeta - 1);
    x = (t) => 1 - Math.exp(-zeta * w0 * t) * (Math.cosh(wd * t) + (zeta * w0 / wd) * Math.sinh(wd * t));
  } else {
    x = (t) => 1 - Math.exp(-w0 * t) * (1 + w0 * t);
  }
  let duration = 0;
  for (let t = 0; t < 3; t += 0.005) if (Math.abs(1 - x(t)) > 0.002) duration = t + 0.005;
  const steps = 40;
  const points = Array.from({ length: steps + 1 }, (_, i) => (i === steps ? 1 : Number(x((duration * i) / steps).toFixed(4))));
  return { easing: `linear(${points.join(', ')})`, duration: Number(duration.toFixed(3)) };
}
/*
 * 界面用到的弹簧（[stiffness, damping]），写成 --spring-<名称> 与 --spring-<名称>-dur（见 app.css）：
 * cover 为竖向布局里封面移动（VerticalLayout），bounce 为进度条、音量条收细时的回弹，edge 为拖过两端时的回弹（BouncingSlider），
 * thumb 为收起按钮的变形（ControlThumb）
 */
const SPRINGS = { cover: [200, 30], bounce: [200, 12], edge: [300, 12], thumb: [300, 26] };

/** 一个声部（主唱或和声）转成一行 AMLL 歌词；和声去掉 Apple 写在词里的括号 */
function amllLine(voice, line, { isBG, isDuet, translation, pronunciation }) {
  const tokens = validTokens(voice);
  const clean = (text) => (isBG ? text.replace(/[()]/g, '') : text);
  const text = plainText(voice);
  // 逐词音译与原文相同（如英文歌）时不显示
  const romanTokens = pronunciation && !tokens.every((t) => t.text === voice.pronunciationTokens[voice.tokens.indexOf(t)]?.text);
  const words = tokens.length
    ? tokens.map((token) => {
      const roman = romanTokens ? voice.pronunciationTokens[voice.tokens.indexOf(token)]?.text : '';
      return {
        startTime: token.begin, endTime: Math.max(token.begin, token.end),
        word: clean(token.text) + (token.spaceAfter ? ' ' : ''),
        ...(roman ? { romanWord: clean(roman) } : {}),
      };
    })
    : [{ startTime: line.begin, endTime: Math.max(line.begin, line.end), word: clean(voice.text) }];
  const begin = Math.min(...words.map((w) => w.startTime));
  const end = Math.max(...words.map((w) => w.endTime));
  return {
    words, startTime: begin, endTime: end, isBG, isDuet,
    translatedLyric: translation && voice.translation && !same(voice.translation, text) ? voice.translation : '',
    romanLyric: pronunciation && voice.pronunciation && !same(voice.pronunciation, text) ? voice.pronunciation : '',
  };
}

/** parseTTML 的结果转成 AMLL LyricLine[]，和声紧跟在所属主歌词行后面 */
export function toAmllLines(song, options) {
  let lastPersonAgentId = null;
  let lastPersonIsDuet = false;
  return song.lines.flatMap((line) => {
    const agentId = line.agent || 'v1';
    const agent = song.agents?.[agentId];
    let isDuet = false;
    // 合唱不改变上一位主唱及其显示侧
    if (agent?.type !== 'group') {
      if (lastPersonAgentId === null) isDuet = agent?.type === 'other';
      else isDuet = lastPersonAgentId === agentId ? lastPersonIsDuet : !lastPersonIsDuet;
      lastPersonAgentId = agentId;
      lastPersonIsDuet = isDuet;
    }
    const main = amllLine(line, line, { ...options, isBG: false, isDuet });
    if (!line.background.tokens.length && !line.background.text) return [main];
    return [main, amllLine(line.background, line, { ...options, isBG: true, isDuet })];
  });
}

/** 是否显示歌词（展开界面里的歌词按钮），保存在浏览器中；存储不可用时默认显示 */
const SHOWN_KEY = 'am-hook:lyrics-hidden';
function loadShown() {
  try { return localStorage.getItem(SHOWN_KEY) !== '1'; } catch { return true; }
}
function saveShown(shown) {
  try { if (shown) localStorage.removeItem(SHOWN_KEY); else localStorage.setItem(SHOWN_KEY, '1'); } catch { /* 只在本次会话生效 */ }
}

/** 歌词选项：字号（AMLL 默认字号的倍数）、字重、歌词来源与背景（'amll' 流动背景 | 'classic' 经典背景），保存在浏览器中 */
const PREFS_KEY = 'am-hook:lyrics-prefs';
export const FONT_SCALES = [0.7, 0.8, 0.9, 1, 1.1, 1.2, 1.35, 1.5];
export const FONT_WEIGHTS = [300, 400, 500, 600, 700, 800];
export const BACKDROPS = ['amll', 'classic'];
const DEFAULT_PREFS = { scale: 1, weight: 600, source: 'apple', backdrop: 'amll' };
function loadPrefs() {
  try {
    const saved = JSON.parse(localStorage.getItem(PREFS_KEY) || '{}');
    return {
      scale: FONT_SCALES.includes(saved.scale) ? saved.scale : DEFAULT_PREFS.scale,
      weight: FONT_WEIGHTS.includes(saved.weight) ? saved.weight : DEFAULT_PREFS.weight,
      source: saved.source === 'amll' ? 'amll' : DEFAULT_PREFS.source,
      backdrop: BACKDROPS.includes(saved.backdrop) ? saved.backdrop : DEFAULT_PREFS.backdrop,
    };
  } catch { return { ...DEFAULT_PREFS }; }
}
function savePrefs(prefs) {
  try { localStorage.setItem(PREFS_KEY, JSON.stringify(prefs)); } catch { /* 只在本次会话生效 */ }
}

/** AMLL TTML DB（https://amll.dev/reference/http-api/native）：按 Apple Music 歌曲 ID 取 TTML，未收录时为 null */
const AMLL_API = 'https://api.amll.dev';
async function fetchAmll(adamId) {
  const response = await fetch(`${AMLL_API}/v1/lyrics/get?appleMusicId=${encodeURIComponent(adamId)}`);
  if (response.status === 404) return null;
  if (!response.ok) throw new Error(`AMLL HTTP ${response.status}`);
  const { data } = await response.json();
  return data?.lyrics ? { text: data.lyrics, source: 'amll', authors: data.authorUsernames || [] } : null;
}

/** 文件名里不能用的字符换成 _ */
const safeName = (name) => name.replace(/[\\/:*?"<>|\u0000-\u001f]+/g, '_').trim().slice(0, 120);

/**
 * root：#lyrics-overlay；toggle：播放条上的歌词按钮（打开歌词；界面里切换是否显示歌词）；bar：播放条，
 * 点击其中非控件区域（封面、标题、空白处）展开界面（没有歌词时也能展开）；界面打开时并入 .lyrics-controls，
 * 歌词按钮与待播清单按钮移到 .lyrics-toggles，关闭时放回原处。
 * getMeta() 返回正在播放的歌曲的 { title, artist, artists, artwork, country? }（artists: [{ name, href }]，用于艺人链接；
 * 有 country 时优先作为请求歌词的地区）；t 为界面文案函数；notify 显示提示。
 * navigate(href)：前端路由，点击艺人链接时关闭界面并由它打开页面（播放不中断）；省略时按普通链接跳转。
 * onShow()：界面展开或展开期间切歌时调用（如更新标题旁的喜爱与「更多」按钮）。
 * 返回 { setTrack(id, country), close() }：setTrack 在切歌时调用，界面跟随正在播放的歌曲；close 收起界面。
 */
export function mountLyrics({ root, toggle, bar, player, getMeta, t, notify, onLangChange, navigate, onShow }) {
  const $ = (selector) => root.querySelector(selector);
  const stage = $('.lyrics-stage');
  const panel = $('.lyric-panel');
  const cover = $('.lyrics-cover');
  const art = $('.lyrics-art');
  const dock = $('.lyrics-dock');
  const controls = $('.lyrics-controls');
  const toggles = $('.lyrics-toggles');
  const phonySmall = $('.lyrics-phony-small');
  const phonyBig = $('.lyrics-phony-big');
  const mainHead = $('.lyrics-head--main');
  const compactHead = $('.lyrics-head--compact');
  const actions = $('.lyrics-actions');
  const thumb = $('.lyrics-thumb');
  const closeButton = $('.lyrics-close');
  const follow = $('.lyrics-follow');
  // 歌名与艺人各占一行，过长时滚动（同 music.apple.com 的 amp-lcd-metadata，见 player.js 的 Marquee）：
  // 主标题行在横向布局的封面下、竖向布局的大封面下，竖向布局显示歌词时用小封面旁的一份
  const heads = [mainHead, compactHead].map((head) => ({
    title: new globalThis.AmHook.Marquee(head.querySelector('.lyrics-title')),
    artist: new globalThis.AmHook.Marquee(head.querySelector('.lyrics-artist')),
  }));
  // 翻译 / 发音：同 music.apple.com，一个「歌词选项」按钮弹出菜单切换；开关在切歌后保留。
  // 同一菜单里还有字号、字重、歌词来源与下载 TTML
  const translationMenu = $('.lyrics-translation-menu');
  const translationButton = $('.lyrics-translation-button');
  const menu = $('.lyrics-menu');
  const scrim = $('.lyrics-menu-scrim');
  // 开关图标：歌词选项（在歌词区一角）用 Apple 的翻译图形，底部的歌词开关与待播清单开关用 react-full 的图形（播放条上仍显示原来的图标，见 app.css）
  const setInverted = toggleIcon(translationButton, { viewBox: '0 0 17 16', paths: TRANSLATE_PATHS, transform: 'translate(-.51 4.44)scale(.101)', inset: 13 });
  const setToggleInverted = toggleIcon(toggle, { paths: [LYRICS_GLYPH] });
  const queueButton = bar.querySelector('.player-queue');
  if (queueButton) {
    const setQueueInverted = toggleIcon(queueButton, { paths: [QUEUE_GLYPH] });
    const syncQueue = () => setQueueInverted(queueButton.getAttribute('aria-expanded') === 'true');
    // 清单打开时歌词开关不反转（两个开关只有当前显示的一个反转）；清单占据歌词的位置，竖向布局随之改为小封面
    new MutationObserver(() => { syncQueue(); syncToggle(); syncMode(); }).observe(queueButton, { attributes: true, attributeFilter: ['aria-expanded'] });
    syncQueue();
  }
  // 点底部开关时不先收起待播清单（见 player.js 的 bindKeys）：歌词开关在清单打开时是「回到歌词」
  toggles.dataset.queueKeep = '';
  // 写在 <html> 上：浮在页面底部的播放条与待播清单也用这套图标
  for (const [name, svg] of Object.entries(MASK_ICONS)) {
    document.documentElement.style.setProperty(`--amll-icon-${name}`, `url("data:image/svg+xml,${encodeURIComponent(svg)}")`);
  }
  if (globalThis.CSS?.supports?.('transition-timing-function', 'linear(0, 1)')) {
    for (const [name, [stiffness, damping]] of Object.entries(SPRINGS)) {
      const { easing, duration } = spring(stiffness, damping);
      root.style.setProperty(`--spring-${name}`, easing);
      root.style.setProperty(`--spring-${name}-dur`, `${duration}s`);
    }
  }
  const shown = { translation: false, pronunciation: false };
  const has = { translation: false, pronunciation: false };
  const prefs = loadPrefs();
  const view = new DomLyricPlayer();
  panel.append(view.getElement());
  const credits = document.createElement('div');
  credits.className = 'lyrics-credits';
  view.getBottomLineElement().append(credits);
  // 按下时底部控件是否已隐藏（.controls-idle）：此时点歌词行只显示控件、不跳转，
  // 控件显示后再点一下（即双击）才跳转；按下时就要记下，抬起时控件已被 wake() 显示
  let pressedWhileIdle = false;
  view.addEventListener('line-click', (event) => {
    if (pressedWhileIdle) return;
    // AMLL 会把行的开始时间提前最多 600ms 用于入场动画；跳转到第一个词的原始时间
    const line = event.line.getLine();
    seek(line.words[0]?.startTime ?? line.startTime);
  });

  let canvas = $('.lyrics-backdrop');
  const motion = matchMedia('(prefers-reduced-motion: reduce)');
  motion.addEventListener('change', () => backdrop?.setStaticMode(motion.matches));
  let backdrop = createBackdrop();

  /**
   * 按 prefs.backdrop 在 canvas 上创建背景，统一成 { setImage(blob) → 是否已显示, resume, pause, setHasLyric, setStaticMode, dispose }；
   * 流动背景不可用（不支持 WebGL）时改用经典背景，都不可用时为 null（保留纯色背景）
   */
  function createBackdrop() {
    // 只有经典背景叠颗粒层（见 app.css .lyrics-grain）；AMLL 不可用时退回经典背景，也要加上
    root.classList.remove('classic-backdrop');
    if (prefs.backdrop === 'amll') {
      try {
        if (MeshGradientRenderer.isSupported()) {
          const render = new BackgroundRender(new MeshGradientRenderer(canvas), canvas);
          render.setHasLyric(true);
          render.setStaticMode(motion.matches);
          render.pause();
          return {
            async setImage(blob) {
              const url = URL.createObjectURL(blob);
              try { await render.setAlbum(url); } finally { URL.revokeObjectURL(url); }
              return true;
            },
            resume: () => render.resume(),
            pause: () => render.pause(),
            setHasLyric: (has) => render.setHasLyric(has),
            setStaticMode: (on) => render.setStaticMode(on),
            // 会移除自己的画布
            dispose: () => render.dispose(),
          };
        }
      } catch (error) {
        console.warn('[am-hook] AMLL 歌词背景不可用，改用经典背景', error);
      }
    }
    try {
      const classic = new ArtworkBackdrop(canvas);
      root.classList.add('classic-backdrop');
      return {
        setImage: (blob) => classic.setFile(blob),
        resume: () => classic.resume(),
        pause: () => classic.pause(),
        // 经典背景不区分有无歌词，自己跟随「减少动态效果」
        setHasLyric() {},
        setStaticMode() {},
        dispose: () => { classic.destroy(); classic.canvas.remove(); },
      };
    } catch (error) {
      console.warn('[am-hook] 歌词背景不可用', error);
      return null;
    }
  }

  /** 切换背景：画布取过 WebGL 上下文或已交给 worker 后不能换绘制方式，换一块新画布重新创建；界面打开时立即载入封面 */
  function setBackdrop(kind) {
    if (kind === prefs.backdrop) return;
    prefs.backdrop = kind;
    savePrefs(prefs);
    artworkController?.abort();
    artworkController = null;
    artworkSource = '';
    root.classList.remove('has-backdrop');
    const old = canvas;
    // 新建而不是 cloneNode：AMLL 会在画布上写内联样式（如 z-index），不能带给经典背景
    canvas = document.createElement('canvas');
    canvas.className = old.className;
    canvas.setAttribute('aria-hidden', 'true');
    canvas.hidden = true;
    old.after(canvas);
    backdrop?.dispose();
    old.remove();
    backdrop = createBackdrop();
    backdrop?.setHasLyric(lyricsVisible);
    if (open) loadArtwork();
  }

  // 播放条、歌词按钮与待播清单按钮在页面里的位置
  const barHome = document.createComment('player');
  const toggleHome = document.createComment('lyrics toggle');
  const queueHome = document.createComment('queue toggle');
  let adamId = null;
  let country = null;
  let song = null;
  // 正在显示的歌词：TTML 原文（下载用）、来源（'apple' | 'amll'）与 AMLL 歌词库的作者
  let lyricsText = '';
  let lyricsSource = null;
  let amllAuthors = [];
  // 选了 AMLL 歌词库却显示 Apple Music 歌词的原因：'missing'（未收录）或 'failed'（请求失败）
  let amllStatus = null;
  let request = null;
  // 这首歌各来源取到的结果（见 loadLyrics）
  let sources = {};
  // 每次切歌或改歌词来源加一，较早的请求返回时据此忽略
  let generation = 0;
  let unavailable = false;
  let open = false;
  // 声场界面盖住歌词界面时停掉背景与逐帧循环（被盖住时浏览器照样绘制），关闭后恢复
  let covered = !!player.sceneOpen;
  let frame = 0;
  let lastFrame = 0;
  let playing = null;
  let artworkSource = '';
  let artworkController = null;
  let lyricsShown = loadShown();
  let lyricsVisible = false;
  // 竖向布局（窗口高大于宽，见 syncLayout）；封面模式：隐藏歌词且没有打开待播清单，横向布局时封面与控件居中、竖向布局时为大封面
  const portrait = matchMedia('(max-aspect-ratio: 1/1)');
  let vertical = null;
  let coverMode = false;
  // 竖向布局显示歌词时，播放中 3 秒没有触摸就隐藏底部的播放控件与开关（.controls-idle，见 app.css）
  let idleTimer = 0;
  let alignAnchor = '';
  let alignPosition = -1;
  // 关闭时滑出的动画（见 hide）
  let leaveTimer = 0;
  let onLeft = null;

  // 没有时间轴的歌词（timing None）每行都是 0：AMLL 把不早于最后一行结束的时间当作歌曲结束、滚到最后，
  // 这里一直给它第一行之前的时间，停在开头
  const viewTime = (ms) => (song?.timing === 'None' ? -1 : ms);

  function currentTime() {
    return viewTime(player.current ? player.transport().currentTime * 1000 : 0);
  }

  function seek(ms) {
    if (!player.current) return;
    const transport = player.transport();
    transport.currentTime = ms / 1000;
    view.setCurrentTime(viewTime(ms), true);
    view.resetScroll();
    if (transport.paused) player.toggle();
  }

  // ---------- 播放条在界面里的样子（react-full 的 PrebuiltMusicControls / BouncingSlider / VolumeControl） ----------
  const seekBar = bar.querySelector('.seek');
  bar.querySelector('.skip-prev')?.insertAdjacentHTML('beforeend', REWIND_ICON);
  bar.querySelector('.skip-next')?.insertAdjacentHTML('beforeend', FORWARD_ICON);
  const volumeBox = bar.querySelector('.player-volume');
  const volumeInput = bar.querySelector('.volume');
  volumeBox?.insertAdjacentHTML('afterbegin', SPEAKER_LOW);
  volumeBox?.insertAdjacentHTML('beforeend', SPEAKER_HIGH);
  // 浮在页面底部的播放条上，静音按钮也用这个喇叭（裁掉四周空白），声波按音量逐条显示，静音时为叉号
  bar.querySelector('.volume-toggle')?.insertAdjacentHTML('beforeend', SPEAKER_HIGH
    .replace('class="amll-speaker amll-speaker--high" viewBox="0 0 43 40"', 'class="amll-volume-icon" viewBox="14 7.5 26 25"')
    .replace('</svg>', '<path class="volume-mute" d="m28.5 15.5 8 8m0-8-8 8" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>'));

  /** 重新开始元素上的 CSS 动画：去掉 className、强制排版后再加上 */
  function replay(element, className) {
    element.classList.remove(className);
    element.getBoundingClientRect();
    element.classList.add(className);
  }

  // 播放控件按下时整体弹一下（MediaButton 的 pressed-animation，只在界面里）；上一首 / 下一首重新插入图标，播放箭头动画
  bar.addEventListener('click', (event) => {
    const button = event.target.closest('.player-toggle, .player-skip, .player-switch');
    if (!button || button.disabled) return;
    if (open) replay(button, 'amll-pressed');
    const icon = button.querySelector('.amll-skip-icon');
    icon?.replaceWith(icon.cloneNode(true));
  });
  controls.addEventListener('animationend', (event) => {
    if (event.animationName === 'amll-pressed') event.target.closest('.amll-pressed')?.classList.remove('amll-pressed');
  });

  // 拖动进度条超出两端时整条被拉过去一点（最多 12px，越远越慢），松开后弹回
  let seekShift = 0;
  seekBar.addEventListener('pointermove', (event) => {
    if (!open || !seekBar.classList.contains('dragging')) return;
    const rect = seekBar.getBoundingClientRect();
    const ratio = (event.clientX - rect.left + seekShift) / rect.width;
    seekShift = ratio < 0 ? Math.tanh(ratio * 2) * 12 : ratio > 1 ? Math.tanh((ratio - 1) * 2) * 12 : 0;
    seekBar.style.translate = seekShift ? `${seekShift}px 0` : '';
  });
  const releaseSeek = () => { seekShift = 0; seekBar.style.translate = ''; };
  seekBar.addEventListener('pointerup', releaseSeek);
  seekBar.addEventListener('pointercancel', releaseSeek);

  // 音量调到 0 / 最大时，对应一端的喇叭弹一下
  let lastVolume = Number(volumeInput?.value);
  volumeInput?.addEventListener('input', () => {
    const value = Number(volumeInput.value);
    if (value === lastVolume) return;
    lastVolume = value;
    const speaker = value <= 0 ? volumeBox.querySelector('.amll-speaker--low') : value >= 1 ? volumeBox.querySelector('.amll-speaker--high') : null;
    if (speaker) replay(speaker, 'amll-speaker--bounce');
  });

  // 点总时长切换为剩余时间（react-full 的 showRemainingTime），保存在浏览器中
  const REMAINING_KEY = 'am-hook:show-remaining';
  try { player.showRemaining = localStorage.getItem(REMAINING_KEY) === '1'; } catch { /* 默认显示总时长 */ }
  bar.querySelector('.time-total')?.addEventListener('click', () => {
    if (!open || !player.current) return;
    player.showRemaining = !player.showRemaining;
    try { localStorage.setItem(REMAINING_KEY, player.showRemaining ? '1' : '0'); } catch { /* 只在本次会话生效 */ }
    player.renderProgress();
  });

  function tick(timestamp) {
    const transport = player.current ? player.transport() : null;
    const now = !!transport && !transport.paused;
    if (now !== playing) {
      playing = now;
      if (now) view.resume(); else view.pause();
      // 暂停时大封面缩小（react-full 的 Cover）
      root.classList.toggle('paused', !now);
      wake();
    }
    // 隐藏歌词时只有背景在动，歌词视图不再排版
    if (lyricsVisible) {
      view.setCurrentTime(viewTime(transport ? transport.currentTime * 1000 : 0));
      view.update(lastFrame ? timestamp - lastFrame : 0);
    }
    lastFrame = timestamp;
    // 进度条每帧跟随播放进度（播放条本身只在 timeupdate 时更新）；拖动时跟随手指
    const duration = player.current ? player.duration() : 0;
    const ratio = player.dragRatio !== undefined ? player.dragRatio : (transport && duration > 0 ? transport.currentTime / duration : 0);
    seekBar.style.setProperty('--progress', String(Math.min(1, Math.max(0, ratio || 0))));
    // AMLL 在用户滚动后暂停自动对齐，下一行进入可视范围时才会自己回来；这里提供立即回到当前行的按钮
    const suspended = lyricsVisible && !!view.scrollState?.isAutoAlignSuspended;
    if (follow.hidden === suspended) follow.hidden = !suspended;
    frame = requestAnimationFrame(tick);
  }

  // ---------- 布局（react-full 的 AutoLyricLayout / HorizontalLayout / VerticalLayout） ----------

  /** 按窗口宽高比选择横向或竖向布局；切换时封面回到网格里（横向）或立即放到目标位置（竖向） */
  function syncLayout() {
    const next = portrait.matches;
    if (next === vertical) return;
    vertical = next;
    root.classList.toggle('layout-v', vertical);
    root.classList.toggle('layout-h', !vertical);
    cover.removeAttribute('style');
    syncMode();
    syncDock();
    placeCover(true);
    wake();
  }

  /**
   * 封面模式与标题行：喜爱与「更多」跟着当前显示的标题行；模式变化时竖向布局的封面移到新位置
   */
  function syncMode() {
    const next = !lyricsVisible && !root.classList.contains('queue-open');
    root.classList.toggle('cover-mode', next);
    const head = vertical && !next ? compactHead : mainHead;
    if (actions.parentElement !== head) head.append(actions);
    if (next === coverMode) return;
    coverMode = next;
    placeCover();
  }

  /**
   * 竖向布局：封面绝对定位在小封面或大封面的占位（.lyrics-phony-*）处，取占位的较短边为边长、居中；
   * 位置改变时按 --spring-cover 过渡（VerticalLayout 的 spring：stiffness 200、damping 30）。instant 时直接到位
   */
  function placeCover(instant = false) {
    if (!vertical || !open) return;
    const target = coverMode ? phonyBig : phonySmall;
    const base = stage.getBoundingClientRect();
    const box = target.getBoundingClientRect();
    const size = Math.max(0, Math.min(box.width, box.height));
    if (instant) cover.classList.add('no-motion');
    Object.assign(cover.style, {
      left: `${box.left - base.left + (box.width - size) / 2}px`,
      top: `${box.top - base.top + (box.height - size) / 2}px`,
      width: `${size}px`, height: `${size}px`,
    });
    if (!instant) return;
    cover.getBoundingClientRect();
    cover.classList.remove('no-motion');
  }

  /**
   * 竖向布局的底部控件叠在歌词区下部：把控件高度写到 --lyrics-controls-h（歌词在控件上方渐隐、大封面让出这块高度，见 app.css）；
   * 横向布局为 0
   */
  function syncDock() {
    root.style.setProperty('--lyrics-controls-h', `${vertical ? dock.offsetHeight : 0}px`);
    syncAlign();
  }

  /**
   * 当前行的位置：横向布局对齐到封面的垂直中心（alignAnchor center），竖向布局在歌词区顶部 10% 处（alignAnchor top），
   * 同 react-full 的 PrebuiltLyricPlayer
   */
  function syncAlign() {
    let anchor = 'top';
    let position = 0.1;
    if (!vertical) {
      anchor = 'center';
      const height = panel.offsetHeight;
      position = height ? (cover.offsetTop + cover.offsetHeight / 2 - panel.offsetTop) / height : 0.5;
    }
    if (anchor === alignAnchor && Math.abs(position - alignPosition) < 0.002) return;
    alignAnchor = anchor;
    alignPosition = position;
    view.setAlignAnchor(anchor);
    view.setAlignPosition(position);
    if (lyricsVisible) view.calcLayout('resize');
  }

  /** 能否隐藏底部控件：竖向布局、正在播放并显示歌词 */
  function canSleep() {
    return open && playing && lyricsVisible && vertical;
  }

  /** 显示底部控件；仍可隐藏时重新计时 */
  function wake() {
    clearTimeout(idleTimer);
    root.classList.remove('controls-idle');
    if (canSleep()) idleTimer = setTimeout(sleep, 3000);
  }

  function sleep() {
    clearTimeout(idleTimer);
    if (!canSleep()) return;
    // 菜单、音质详情或待播清单打开时保持显示
    if (!menu.hidden || $('.quality-panel')?.hidden === false || root.classList.contains('queue-open')) { wake(); return; }
    root.classList.add('controls-idle');
  }

  function renderHeader() {
    const meta = getMeta();
    if (meta.artwork) { if (art.getAttribute('src') !== meta.artwork) art.src = meta.artwork; } else art.removeAttribute('src');
    art.hidden = !meta.artwork;
    for (const head of heads) {
      head.title.set([document.createTextNode(meta.title || t('player.unknownTitle'))]);
      // 艺人名链接到艺人页（见 player.js 的 artistNodes）
      head.artist.set(globalThis.AmHook.artistNodes(meta.artist || '', meta.artists));
    }
  }

  function renderCredits() {
    if (!song) return;
    credits.replaceChildren();
    if (song.credits.length) {
      const label = document.createElement('span');
      label.className = 'credit-label';
      label.textContent = t('lyrics.credits');
      const names = document.createElement('span');
      names.className = 'credit-names';
      names.textContent = song.credits.join(t('lyrics.creditsSeparator'));
      credits.append(label, names);
    }
    if (song.translation.automatic && shown.translation) {
      const note = document.createElement('div');
      note.className = 'translation-note';
      note.textContent = t('lyrics.aiTranslation');
      credits.append(note);
    }
    if (lyricsSource === 'amll') {
      const note = document.createElement('div');
      note.className = 'source-note';
      note.textContent = amllAuthors.length
        ? t('lyrics.amllCredit', { authors: amllAuthors.map((name) => `@${name}`).join(t('lyrics.creditsSeparator')) })
        : t('lyrics.amllCreditAnon');
      credits.append(note);
    }
  }

  /** 字号与字重写在歌词界面的 CSS 变量上（见 app.css 的 .lyric-panel） */
  function applyPrefs() {
    root.style.setProperty('--lyrics-font-scale', String(prefs.scale));
    root.style.setProperty('--lyrics-font-weight', String(prefs.weight));
  }

  /** 改了字号或字重后重新排版：AMLL 只在尺寸变化时读取字号，行高要按新字号重新计算 */
  function relayout() {
    view.onResize();
    if (!lyricsVisible || !song) return;
    view.rebuildLyricView(currentTime());
    view.setCurrentTime(currentTime(), true);
    view.resetScroll();
  }

  /** 选定的来源没有这首歌的歌词、改用另一来源时的说明 */
  function sourceNote() {
    if (!lyricsSource || lyricsSource === prefs.source) return '';
    if (prefs.source === 'apple') return t('lyrics.appleMissing');
    return t(amllStatus === 'failed' ? 'lyrics.amllFailed' : 'lyrics.amllMissing');
  }

  /** 下载正在显示的歌词（Apple Music 或 AMLL 歌词库的 TTML 原文），文件名为「艺人 - 歌名.ttml」 */
  function downloadTTML() {
    if (!lyricsText) return;
    const meta = getMeta();
    const name = safeName([meta.artist, meta.title].filter(Boolean).join(' - ')) || adamId;
    const url = URL.createObjectURL(new Blob([lyricsText], { type: 'application/ttml+xml' }));
    const a = Object.assign(document.createElement('a'), { href: url, download: `${name}.ttml` });
    a.style.display = 'none';
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60000);
  }

  /** 背景使用页面已有的封面；取不到封面或背景不可用时保留纯色背景 */
  function loadArtwork() {
    const target = backdrop;
    if (!target) return;
    const source = getMeta().artwork || '';
    if (source === artworkSource) { if (!covered) target.resume(); return; }
    artworkSource = source;
    if (artworkController) artworkController.abort();
    artworkController = null;
    if (!source) { canvas.hidden = true; root.classList.remove('has-backdrop'); return; }
    const controller = new AbortController();
    artworkController = controller;
    fetch(source, { signal: controller.signal, cache: 'force-cache' })
      .then((response) => {
        if (!response.ok) throw new Error(`Artwork HTTP ${response.status}`);
        return response.blob();
      })
      .then(async (blob) => {
        if (controller.signal.aborted) return;
        // 切换背景时会中止这次加载（见 setBackdrop），中止后不再碰已销毁的背景
        const shown = await target.setImage(blob);
        if (!shown || controller.signal.aborted) return;
        canvas.hidden = false;
        root.classList.add('has-backdrop');
        if (open && !covered) target.resume(); else target.pause();
      })
      .catch((error) => { if (!controller.signal.aborted) console.warn('[am-hook] 歌词背景加载失败', error); });
  }

  function setLines() {
    view.setLyricLines(toAmllLines(song, shown), currentTime());
    renderCredits();
  }

  /** 歌词按钮的文案：播放条上为「歌词」，界面里为「显示 / 隐藏歌词」，按下状态表示歌词正在显示 */
  function syncToggle() {
    const label = t(open ? (lyricsVisible ? 'lyrics.hide' : 'lyrics.show') : 'lyrics.open');
    toggle.title = label;
    toggle.setAttribute('aria-label', label);
    toggle.setAttribute('aria-pressed', String(open && lyricsVisible));
    setToggleInverted(open && lyricsVisible && !root.classList.contains('queue-open'));
  }

  /**
   * 按「是否显示歌词」与歌曲有没有歌词切换布局（加载中按有歌词处理，避免切歌时布局跳动）；
   * 歌词从隐藏变为显示时，视图需要可见时的尺寸来排版，按当前进度重新对齐
   */
  function applyVisibility() {
    const visible = open && lyricsShown && !unavailable;
    const changed = visible !== lyricsVisible;
    lyricsVisible = visible;
    root.classList.toggle('lyrics-hidden', !visible);
    if (!visible) { closeMenu(); follow.hidden = true; }
    backdrop?.setHasLyric(visible);
    syncToggle();
    syncMode();
    wake();
    syncDock();
    if (!visible || !changed || !song) return;
    if (!view.getLyricLines().length) setLines();
    else view.rebuildLyricView(currentTime());
    view.setCurrentTime(currentTime(), true);
    view.resetScroll();
  }

  function setShown(shown) {
    lyricsShown = shown;
    saveShown(shown);
    applyVisibility();
  }

  /** 播放条与两个开关移进界面（已在界面里时不动） */
  function dockBar() {
    if (controls.contains(bar)) return;
    toggle.replaceWith(toggleHome);
    queueButton?.replaceWith(queueHome);
    toggles.append(toggle, ...(queueButton ? [queueButton] : []));
    bar.replaceWith(barHome);
    controls.append(bar);
  }

  function undockBar() {
    if (!controls.contains(bar)) return;
    barHome.replaceWith(bar);
    toggleHome.replaceWith(toggle);
    if (queueButton) queueHome.replaceWith(queueButton);
  }

  function stopLeaving() {
    clearTimeout(leaveTimer);
    if (onLeft) root.removeEventListener('transitionend', onLeft);
    onLeft = null;
    root.classList.remove('leaving');
  }

  function show() {
    if (open || !adamId) return;
    open = true;
    player.closeQueue();
    // 关闭的动画还没结束时再次打开：从当前位置滑回来
    const reopening = !root.hidden;
    stopLeaving();
    dockBar();
    root.style.transform = '';
    root.hidden = false;
    // 从底部滑入：先放在屏幕下方，排版后去掉，按 app.css 的过渡移上来
    if (!reopening && !motion.matches) {
      root.classList.add('entering');
      root.getBoundingClientRect();
      root.classList.remove('entering');
    }
    document.body.classList.add('lyrics-open');
    renderHeader();
    loadArtwork();
    lyricsVisible = false;
    syncLayout();
    applyVisibility();
    placeCover(true);
    playing = null;
    lastFrame = 0;
    if (!covered) frame = requestAnimationFrame(tick);
    // 焦点移到收起按钮，但不显示焦点框（否则它一打开就变成 ✕）；之后按 Tab 时照常显示
    closeButton.focus({ preventScroll: true, focusVisible: false });
    onShow?.();
  }

  function hide() {
    if (!open) return;
    open = false;
    closeMenu();
    player.closeQueue();
    lyricsVisible = false;
    syncToggle();
    wake();
    cancelAnimationFrame(frame);
    frame = 0;
    backdrop?.pause();
    const refocus = root.contains(document.activeElement) || document.activeElement === document.body;
    // 滑出后再把播放条放回页面、隐藏界面；减少动态效果时立即完成
    const finish = () => {
      stopLeaving();
      if (open) return;
      root.style.transform = '';
      undockBar();
      root.hidden = true;
      document.body.classList.remove('lyrics-open');
      if (refocus) toggle.focus({ preventScroll: true });
    };
    if (motion.matches) { finish(); return; }
    stopLeaving();
    root.style.transition = '';
    root.style.transform = '';
    root.classList.add('leaving');
    onLeft = (event) => { if (event.target === root && event.propertyName === 'transform') finish(); };
    root.addEventListener('transitionend', onLeft);
    leaveTimer = setTimeout(finish, 800);
  }

  /** 有歌词时显示按钮（菜单里还有翻译以外的选项）；开启翻译或发音时图标反转 */
  function syncOptions() {
    translationMenu.hidden = !song;
    setInverted(shown.translation || shown.pronunciation);
    if (!menu.hidden) renderMenu();
  }

  const menuNode = (tag, className, text) => {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text) node.textContent = text;
    return node;
  };
  const menuItem = (child, role = 'none', className = '') => {
    const item = menuNode('li', className);
    item.setAttribute('role', role);
    if (child) item.append(child);
    return item;
  };

  /** 一个菜单项：option 为翻译 / 发音开关，action 为其他操作；checked 不为 undefined 时是单选项 */
  function menuButton({ label, icon, option, action, value, checked, disabled }) {
    const button = menuNode('button');
    button.type = 'button';
    button.setAttribute('role', checked === undefined ? 'menuitem' : 'menuitemradio');
    if (checked !== undefined) button.setAttribute('aria-checked', String(checked));
    if (option) button.dataset.option = option;
    if (action) button.dataset.action = action;
    if (value) button.dataset.value = value;
    button.disabled = !!disabled;
    button.title = label;
    const iconNode = menuNode('span', 'lyrics-menu-icon');
    if (icon) iconNode.innerHTML = MENU_ICONS[icon];
    button.append(menuNode('span', 'lyrics-menu-text', label), iconNode);
    return button;
  }

  /** 字号 / 字重一行：名称、减小按钮、当前值、增大按钮；到头时对应按钮置灰 */
  function stepper(label, value, [less, canLess], [more, canMore]) {
    const row = menuNode('div', 'lyrics-menu-stepper');
    const step = (action, enabled, icon) => {
      const button = menuNode('button', 'lyrics-menu-step');
      button.type = 'button';
      button.setAttribute('role', 'menuitem');
      button.dataset.action = action;
      button.disabled = !enabled;
      button.title = t(`lyrics.${action}`);
      button.setAttribute('aria-label', `${button.title} (${label}: ${value})`);
      button.innerHTML = MENU_ICONS[icon];
      return button;
    };
    row.append(menuNode('span', 'lyrics-menu-text', label), step(less, canLess, 'minus'), menuNode('span', 'lyrics-menu-value', value), step(more, canMore, 'plus'));
    return row;
  }

  /**
   * 菜单分五组：翻译 / 发音（同 music.apple.com：已开启的显示「隐藏…」，否则「显示…」，歌曲没有的一项置灰）、
   * 字号与字重、歌词来源（单选，选定的来源没有这首歌时在下面说明）、背景（单选）、下载 TTML
   */
  function renderMenu() {
    const scale = FONT_SCALES.indexOf(prefs.scale);
    const weight = FONT_WEIGHTS.indexOf(prefs.weight);
    const note = sourceNote();
    const separator = () => menuItem(null, 'separator', 'lyrics-menu-separator');
    const items = [
      ...[
        ['translation', has.translation && shown.translation ? 'hideTranslation' : 'showTranslation'],
        ['pronunciation', has.pronunciation && shown.pronunciation ? 'hidePronunciation' : 'showPronunciation'],
      ].map(([name, action]) => menuItem(menuButton({ label: t(`lyrics.${action}`), icon: action, option: name, disabled: !has[name] }))),
      separator(),
      menuItem(stepper(t('lyrics.fontSize'), `${Math.round(prefs.scale * 100)}%`,
        ['fontSmaller', scale > 0], ['fontLarger', scale < FONT_SCALES.length - 1])),
      menuItem(stepper(t('lyrics.fontWeight'), t(`lyrics.weight${prefs.weight}`),
        ['weightLighter', weight > 0], ['weightBolder', weight < FONT_WEIGHTS.length - 1])),
      separator(),
      menuItem(menuNode('span', '', t('lyrics.source')), 'presentation', 'lyrics-menu-heading'),
      ...['apple', 'amll'].map((source) => menuItem(menuButton({
        label: t(source === 'apple' ? 'lyrics.sourceApple' : 'lyrics.sourceAmll'),
        icon: prefs.source === source ? 'check' : '', action: 'source', value: source, checked: prefs.source === source,
      }))),
      ...(note ? [menuItem(menuNode('span', '', note), 'presentation', 'lyrics-menu-note')] : []),
      separator(),
      menuItem(menuNode('span', '', t('lyrics.backdrop')), 'presentation', 'lyrics-menu-heading'),
      ...BACKDROPS.map((kind) => menuItem(menuButton({
        label: t(kind === 'amll' ? 'lyrics.backdropAmll' : 'lyrics.backdropClassic'),
        icon: prefs.backdrop === kind ? 'check' : '', action: 'backdrop', value: kind, checked: prefs.backdrop === kind,
      }))),
      separator(),
      menuItem(menuButton({ label: t('lyrics.download'), icon: 'download', action: 'download', disabled: !lyricsText })),
    ];
    menu.replaceChildren(...items);
  }

  /** 字号 / 字重按钮：在可选值里前后移一档 */
  const STEPS = {
    fontSmaller: ['scale', FONT_SCALES, -1], fontLarger: ['scale', FONT_SCALES, 1],
    weightLighter: ['weight', FONT_WEIGHTS, -1], weightBolder: ['weight', FONT_WEIGHTS, 1],
  };
  function step(action) {
    const [key, values, delta] = STEPS[action];
    const index = Math.max(0, Math.min(values.length - 1, values.indexOf(prefs[key]) + delta));
    if (values[index] === prefs[key]) return;
    prefs[key] = values[index];
    savePrefs(prefs);
    applyPrefs();
    relayout();
  }

  /** 改歌词来源后重新取这首歌的歌词；结果不是选定的来源时提示原因 */
  function setSource(source) {
    if (source === prefs.source) return;
    prefs.source = source;
    savePrefs(prefs);
    // 还没请求过的歌曲在打开时按新来源请求；正在加载的按新来源重新请求
    if (!adamId || !request || lyricsSource === source) return;
    const id = adamId;
    request = null;
    fetchLyrics().then(() => {
      const note = id === adamId && sourceNote();
      if (note) notify(note);
    });
  }

  /**
   * 在点击处弹出菜单（键盘打开时在按钮中心），同 amp-contextual-menu-button：
   * 右侧放不下时改到左侧，下方放不下（留 40px）时改为向上展开。
   */
  function openMenu(event) {
    renderMenu();
    menu.hidden = false;
    scrim.hidden = false;
    translationButton.setAttribute('aria-expanded', 'true');
    const rect = translationButton.getBoundingClientRect();
    const x = event.clientX || rect.left + rect.width / 2;
    const y = event.clientY || rect.top + rect.height / 2;
    menu.style.cssText = '';
    if (!matchMedia('(max-width: 483px)').matches) {
      const rtl = document.dir === 'rtl';
      const fitsRight = innerWidth - x > menu.offsetWidth;
      const left = (rtl && (x > menu.offsetWidth || !fitsRight)) || (!rtl && !fitsRight) ? x - menu.offsetWidth - 1 : x + 1;
      menu.style.left = `${left}px`;
      if (innerHeight - y > menu.offsetHeight + 40) menu.style.top = `${y}px`;
      else menu.style.bottom = `${innerHeight - y}px`;
    }
    if (!event.detail) menu.querySelector('button:not(:disabled)')?.focus();
  }

  function closeMenu(focusButton) {
    if (menu.hidden) return;
    menu.hidden = true;
    scrim.hidden = true;
    translationButton.setAttribute('aria-expanded', 'false');
    if (focusButton) translationButton.focus({ preventScroll: true });
  }

  /**
   * 按歌词来源取一首歌的歌词：{ song, text, source, authors, amllStatus }，没有歌词时只有 amllStatus。
   * 选了 AMLL 歌词库时先查它，未收录、请求失败或解析不了时记下原因，改用 Apple Music 歌词。
   */
  async function loadLyrics(id) {
    // 这首歌各来源的结果记在 sources 里，来回切换来源时不重复请求；AMLL 歌词库未收录时不记，下次选择时重新查
    const cache = sources;
    const remember = (source, fetcher) => (cache[source] ??= fetcher().then((result) => {
      if (!result && source === 'amll') delete cache[source];
      return result;
    }, (error) => { delete cache[source]; throw error; }));
    const parse = (result) => {
      const parsed = result && parseTTML(result.text);
      return parsed?.lines.length ? { ...result, song: parsed } : null;
    };
    let status = null;
    if (prefs.source === 'amll') {
      try {
        const found = parse(await remember('amll', () => fetchAmll(id)));
        if (found) return { ...found, amllStatus: status };
        status = 'missing';
      } catch (error) {
        console.warn('[am-hook] AMLL 歌词库请求失败', error);
        status = 'failed';
      }
    }
    const apple = await remember('apple', async () => {
      const language = await (async () => globalThis.AmI18n?.catalogLang(getMeta()?.country || country))().catch(() => undefined);
      const text = await globalThis.AmWrapper.lyrics(id, language);
      return text == null ? null : { text, source: 'apple' };
    });
    return { ...parse(apple), amllStatus: status };
  }

  /** 首次打开时获取歌词（改歌词来源后重新获取）；加载中的重复点击被忽略，失败后可重试 */
  function fetchLyrics() {
    if (!request) {
      const id = adamId;
      const current = ++generation;
      const stale = () => current !== generation; // 已切换到另一首歌或改了歌词来源
      toggle.setAttribute('aria-busy', 'true');
      request = loadLyrics(id)
        .then((result) => {
          if (stale()) return;
          if (!result.song) {
            // 改歌词来源后新来源没有歌词：保留正在显示的歌词（菜单里说明）
            if (song) return;
            // 展开界面保持打开，只显示封面与播放控件
            unavailable = true;
            toggle.hidden = true;
            applyVisibility();
            return;
          }
          song = result.song;
          lyricsText = result.text;
          lyricsSource = result.source;
          amllStatus = result.amllStatus;
          amllAuthors = result.source === 'amll' ? (result.authors.length ? result.authors : song.authors) : [];
          view.getElement().lang = song.language;
          const voices = song.lines.flatMap((line) => [line, line.background]);
          has.translation = voices.some((voice) => voice.translation);
          has.pronunciation = voices.some((voice) => voice.pronunciation || voice.pronunciationTokens.length);
          syncOptions();
          // 展开界面里正在等这首歌的歌词时直接排版
          if (lyricsVisible) {
            setLines();
            view.setCurrentTime(currentTime(), true);
            view.resetScroll();
          } else {
            // 改歌词来源时可能已有上一来源的歌词行，清掉后再次显示时按新歌词排版（见 applyVisibility）
            view.setLyricLines([]);
          }
        })
        .catch((error) => {
          if (stale()) return;
          request = null;
          console.warn('[am-hook] 歌词加载失败', error);
          notify(t('lyrics.failed'));
        })
        .finally(() => { if (!stale()) toggle.removeAttribute('aria-busy'); });
    }
    return request;
  }

  /** 切换歌曲（id 为空表示没有歌曲）：歌词界面打开时取回新歌词原地刷新，没有歌词时只显示封面与播放控件 */
  function setTrack(id, cc) {
    id = id || null;
    if (id === adamId) return;
    adamId = id;
    country = cc || null;
    song = null;
    lyricsText = '';
    lyricsSource = amllStatus = null;
    amllAuthors = [];
    request = null;
    sources = {};
    generation++;
    unavailable = false;
    toggle.removeAttribute('aria-busy');
    credits.replaceChildren();
    view.setLyricLines([]);
    closeMenu();
    has.translation = has.pronunciation = false;
    syncOptions();
    toggle.hidden = !id;
    bar.classList.toggle('lyrics-available', !!id);
    if (!open) return;
    if (!id) { hide(); return; }
    renderHeader();
    loadArtwork();
    applyVisibility();
    onShow?.();
    fetchLyrics();
  }

  /** 播放条上的歌词按钮：打开界面并显示歌词（没有歌词时提示，不展开）；展开后切换是否显示歌词 */
  function onToggle() {
    // 手机上待播清单占着歌词的位置：这时点歌词开关是回到歌词
    if (open && root.classList.contains('queue-open')) { player.closeQueue(); if (!lyricsShown) setShown(true); return; }
    if (open) { setShown(!lyricsShown); return; }
    if (song) { setShown(true); show(); return; }
    if (unavailable || toggle.hasAttribute('aria-busy')) return;
    const id = adamId;
    fetchLyrics().then(() => {
      if (id !== adamId || open) return;
      if (song) { setShown(true); show(); } else if (unavailable) notify(t('lyrics.none'));
    });
  }

  toggle.addEventListener('click', onToggle);
  // 点击播放条展开界面，按上次的选择显示或隐藏歌词；歌词随后取回
  bar.addEventListener('click', (event) => {
    if (open || !adamId || event.target.closest('button, input, a, [role="slider"], .player-volume, .player-msg')) return;
    show();
    fetchLyrics();
  });

  // 收起按钮（ControlThumb）：鼠标移上去时变成 ✕，在按钮范围内以一半的速度跟随指针
  let dragged = false;
  closeButton.addEventListener('click', () => { if (!dragged) hide(); dragged = false; });
  closeButton.addEventListener('pointermove', (event) => {
    if (event.pointerType !== 'mouse') return;
    const box = thumb.getBoundingClientRect();
    const half = (offset) => `${Math.max(-12.5, Math.min(12.5, offset / 2))}px`;
    closeButton.style.setProperty('--thumb-x', half(event.clientX - box.left - box.width / 2));
    closeButton.style.setProperty('--thumb-y', half(event.clientY - box.top - box.height / 2));
  });
  closeButton.addEventListener('pointerleave', () => {
    closeButton.style.removeProperty('--thumb-x');
    closeButton.style.removeProperty('--thumb-y');
  });
  // 触屏上按住收起按钮所在的一行向下拖：界面跟着手指下移，拖过 120px 或快速下滑时收起，否则弹回
  let drag = null;
  thumb.addEventListener('pointerdown', (event) => {
    if (!open || event.pointerType === 'mouse' || drag) return;
    drag = { id: event.pointerId, y: event.clientY, dy: 0, time: event.timeStamp, speed: 0 };
    dragged = false;
    thumb.setPointerCapture(event.pointerId);
  });
  thumb.addEventListener('pointermove', (event) => {
    if (!drag || event.pointerId !== drag.id) return;
    const dy = Math.max(0, event.clientY - drag.y);
    drag.speed = (dy - drag.dy) / Math.max(1, event.timeStamp - drag.time);
    drag.dy = dy;
    drag.time = event.timeStamp;
    if (dy > 6) dragged = true;
    root.style.transition = 'none';
    root.style.transform = dy ? `translateY(${dy}px)` : '';
  });
  const endDrag = (event) => {
    if (!drag || event.pointerId !== drag.id) return;
    const { dy, speed } = drag;
    drag = null;
    root.style.transition = '';
    if (dy > 120 || (dy > 24 && speed > 0.5)) hide();
    else root.style.transform = '';
  };
  thumb.addEventListener('pointerup', endDrag);
  thumb.addEventListener('pointercancel', endDrag);

  // 竖向布局里点封面：显示歌词时回到大封面，大封面时显示歌词，待播清单打开时收起清单
  cover.addEventListener('click', () => {
    if (!open || !vertical) return;
    if (root.classList.contains('queue-open')) player.closeQueue();
    else if (lyricsVisible) setShown(false);
    else if (!unavailable) setShown(true);
  });

  root.addEventListener('click', (event) => {
    const link = event.target.closest('.lyrics-artist a');
    if (!link || !navigate || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    hide();
    navigate(link.getAttribute('href'));
  });
  translationButton.addEventListener('click', (event) => {
    if (menu.hidden) openMenu(event); else closeMenu();
  });
  scrim.addEventListener('click', () => closeMenu());
  menu.addEventListener('click', (event) => {
    const button = event.target.closest('button');
    if (!button || button.disabled) return;
    const { option, action, value } = button.dataset;
    if (option) {
      shown[option] = !shown[option];
      closeMenu(true);
      syncOptions();
      setLines();
    } else if (action === 'source') {
      closeMenu(true);
      setSource(value);
    } else if (action === 'backdrop') {
      closeMenu(true);
      setBackdrop(value);
    } else if (action === 'download') {
      closeMenu(true);
      downloadTTML();
    } else if (STEPS[action]) {
      // 字号 / 字重：菜单保持打开，可以连续调整；焦点留在同一按钮（到头置灰时移到另一侧）
      const focused = document.activeElement === button;
      step(action);
      renderMenu();
      if (!focused) return;
      const again = menu.querySelector(`[data-action="${action}"]`);
      (again.disabled ? again.parentElement.querySelector('.lyrics-menu-step:not(:disabled)') : again)?.focus();
    }
  });
  menu.addEventListener('keydown', (event) => {
    if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return;
    event.preventDefault();
    const buttons = [...menu.querySelectorAll('button:not(:disabled)')];
    const index = buttons.indexOf(document.activeElement) + (event.key === 'ArrowDown' ? 1 : -1);
    buttons[(index + buttons.length) % buttons.length]?.focus();
  });
  follow.addEventListener('click', () => { view.resetScroll(); follow.hidden = true; });
  // 手指上滑立即隐藏底部控件、下滑显示（一次滑动中换向时跟随最新方向），轻点也显示；
  // 用 touch 事件而非 pointer 事件，浏览器接管滚动后仍能收到 touchmove
  let touchY = null;
  let swiped = false;
  root.addEventListener('touchstart', (event) => {
    touchY = event.touches.length === 1 ? event.touches[0].clientY : null;
    swiped = false;
  }, { capture: true, passive: true });
  root.addEventListener('touchmove', (event) => {
    if (touchY === null || event.touches.length !== 1) return;
    const y = event.touches[0].clientY;
    if (Math.abs(y - touchY) < 12) return;
    if (y < touchY) sleep(); else wake();
    touchY = y;
    swiped = true;
  }, { capture: true, passive: true });
  root.addEventListener('touchend', () => {
    if (touchY !== null && !swiped) wake();
    touchY = null;
  }, { capture: true, passive: true });
  root.addEventListener('touchcancel', () => { touchY = null; }, { capture: true, passive: true });
  // 鼠标、触控笔点击或键盘焦点进入界面时显示
  root.addEventListener('pointerdown', (event) => {
    pressedWhileIdle = root.classList.contains('controls-idle');
    // 触摸后 :hover 会停留在这一行，不跳转时不显示行的底框（见 app.css），下次按下时恢复
    root.classList.toggle('lyrics-tap-muted', pressedWhileIdle);
    if (event.pointerType !== 'touch') wake();
  }, true);
  root.addEventListener('focusin', wake);
  portrait.addEventListener('change', syncLayout);
  // 尺寸变化时重新计算控件高度、歌词对齐与封面位置；待播清单跟着占位移动
  const resizeObserver = new ResizeObserver(() => {
    if (!open) return;
    syncDock();
    placeCover();
    player.placeQueue();
  });
  for (const element of [stage, dock, panel, phonySmall, phonyBig]) resizeObserver.observe(element);
  document.addEventListener('keydown', (event) => {
    // 已由其他菜单处理（如标题旁「更多」的菜单）
    if (!open || event.key !== 'Escape' || event.defaultPrevented) return;
    event.preventDefault();
    // 菜单打开时 Esc 只关闭菜单
    if (!menu.hidden) closeMenu(true); else hide();
  });
  onLangChange(() => {
    renderCredits();
    if (!menu.hidden) renderMenu();
    if (open) renderHeader();
    syncToggle();
  });
  player.onSceneOpen((on) => {
    covered = on;
    if (!open) return;
    if (on) {
      cancelAnimationFrame(frame);
      frame = 0;
      backdrop?.pause();
      return;
    }
    // 被盖住期间可能换了曲目或暂停了播放：重新同步播放状态，背景按当前封面恢复
    playing = null;
    lastFrame = 0;
    if (!frame) frame = requestAnimationFrame(tick);
    loadArtwork();
  });
  applyPrefs();
  syncLayout();
  syncToggle();

  return { setTrack, close: hide };
}
